<script setup lang="ts">
import {computed,ref} from 'vue';
import {ElDialog,ElButton,ElMessage} from 'element-plus';
import {usePhase1} from '@/pinia/phase1';
import {agentWorkData} from '@/pinia/agentWork';
import type {P1SkillId} from '@/views/AgentWork/interface';
import {phaseSkills} from './catalog';import {taskParameters} from './ruleLanguage';import RuleAssistant from './RuleAssistant.vue';
const props=defineProps<{projectId:string;taskId:P1SkillId}>();const emit=defineEmits<{close:[]}>();const s=usePhase1();const work=agentWorkData();const baseline=s.config(props.projectId).version;const draft=ref(s.config(props.projectId));const task=computed(()=>phaseSkills.find(t=>t.id===props.taskId)!);const error=ref('');const parameters=computed(()=>taskParameters(draft.value,props.taskId).filter(parameter=>!parameter.key.endsWith('enabled')));
function save(){if(!s.saveConfig(props.projectId,draft.value,baseline)){error.value=s.error;return;}const p=work.projects.find(p=>p.id===props.projectId);if(p)p.skillIds=[...(p.skillIds||[]).filter(x=>!phaseSkills.some(t=>t.id===x)),...s.config(props.projectId).selectedSkills];ElMessage.success('任务规则与项目配置已更新');emit('close');}
</script>
<template><ElDialog :model-value="true" title="编辑监控任务" width="640px" style="max-width:calc(100vw - 32px)" :close-on-click-modal="false" @close="emit('close')"><div class="monitor-form"><label>任务名称<input :value="task.name" readonly aria-label="任务名称"/></label><h3>任务说明</h3><p>{{task.description}}</p><h3>任务规则</h3><dl class="rule-parameters"><div v-for="parameter in parameters" :key="parameter.key"><dt>{{parameter.label}}</dt><dd><strong>{{parameter.value}}</strong></dd></div></dl><details class="rule-help"><summary>查看规则说明</summary><p v-for="parameter in parameters" :key="parameter.key"><span>{{parameter.label}}：</span>{{parameter.note}}</p></details><RuleAssistant :config="draft" :scope="taskId" @confirm="draft=$event.config"/><p class="p1-error" role="alert">{{error}}</p></div><template #footer><ElButton @click="emit('close')">取消</ElButton><ElButton type="primary" @click="save">保存任务</ElButton></template></ElDialog></template>
<style scoped>
.monitor-form{font-size:14px;line-height:1.6}.monitor-form label,.monitor-form input{display:block;width:100%}.monitor-form input{margin-top:6px;padding:8px 10px;border:1px solid #ddd;border-radius:5px;background:#f7f7f7}.monitor-form h3{font-size:13px;margin:14px 0 6px;font-weight:600}.monitor-form p{margin:5px 0}.rule-parameters{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:24px;margin:6px 0 4px;padding:4px 0;border-top:1px solid #e5e7eb;border-bottom:1px solid #e5e7eb}.rule-parameters>div{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:7px 0;min-width:0}.rule-parameters dt{color:#667487;font-size:13px;flex-shrink:0}.rule-parameters dd{margin:0;text-align:right;overflow-wrap:anywhere}.rule-parameters strong{font-weight:500}.rule-help{font-size:12px;color:#667487;margin-top:7px}.rule-help summary{cursor:pointer;width:fit-content}.rule-help p{margin:6px 0}.rule-help span{color:#344054}@media(max-width:560px){.rule-parameters{grid-template-columns:1fr}}
</style>
